"use client"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Building2, Users, Globe, Mail } from "lucide-react"
import type { Company } from "@/lib/api"

interface CompanyCardProps {
  company: Company
  onClick?: () => void
}

function formatCurrency(amount: number | null): string {
  if (amount === null) return "N/A"
  return `RWF ${amount.toLocaleString()}`
}

function formatDate(dateString: string | null): string {
  if (!dateString) return "N/A"
  return new Date(dateString).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
  })
}

export function CompanyCard({ company, onClick }: CompanyCardProps) {
  // Add null/undefined check
  if (!company) {
    return null
  }

  return (
    <div
      onClick={onClick}
      className={cn(
        "bg-card p-6 rounded-lg border border-border transition-all",
        onClick && "cursor-pointer hover:shadow-md hover:-translate-y-0.5 hover:border-primary"
      )}
    >
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1 min-w-0">
          <h3 className="font-semibold text-foreground truncate">{company.name}</h3>
          <p className="text-sm text-muted-foreground capitalize">{company.industry}</p>
        </div>
        <Badge
          variant="outline"
          className={cn(
            company.isActive
              ? "bg-chart-1/10 text-chart-1 border-chart-1/20"
              : "bg-warning/10 text-warning border-warning/20"
          )}
        >
          {company.isActive ? "Active" : "Inactive"}
        </Badge>
      </div>
      
      {company.description && (
        <p className="text-sm text-muted-foreground mb-4 line-clamp-2">
          {company.description}
        </p>
      )}
      
      <div className="grid grid-cols-2 gap-4 mb-4">
        <div>
          <p className="text-xs text-muted-foreground mb-1">Annual Revenue</p>
          <p className="font-serif font-semibold text-foreground tabular-nums">
            {formatCurrency(company.annualRevenue)}
          </p>
        </div>
        <div>
          <p className="text-xs text-muted-foreground mb-1">Employees</p>
          <p className="font-serif font-semibold text-foreground tabular-nums">
            {company.employeeCount}
          </p>
        </div>
        <div>
          <p className="text-xs text-muted-foreground mb-1">Company Type</p>
          <p className="font-serif font-semibold text-foreground capitalize">
            {company.companyType}
          </p>
        </div>
        <div>
          <p className="text-xs text-muted-foreground mb-1">Established</p>
          <p className="font-serif font-semibold text-foreground">
            {formatDate(company.establishedDate)}
          </p>
        </div>
      </div>
      
      <div className="flex flex-wrap gap-2 text-xs text-muted-foreground">
        {company.ceo && (
          <span className="flex items-center gap-1">
            <Building2 className="h-3 w-3" />
            {company.ceo}
          </span>
        )}
        {company.email && (
          <span className="flex items-center gap-1">
            <Mail className="h-3 w-3" />
            {company.email}
          </span>
        )}
        {company.website && (
          <span className="flex items-center gap-1">
            <Globe className="h-3 w-3" />
            {company.website.replace(/https?:\/\//, "")}
          </span>
        )}
      </div>
    </div>
  )
}